package glitch

import data.glitch_lib

hardcoded_credential_keywords := {"password", "secret", "key", "token", "credential", "api_key", "auth", "pass", "passwd", "secret_key", "access_key", "private_key"}

config_keywords := {"config_file", "properties", "env_file", "inline_config"}

env_keywords := {"environment", "env_vars", "variables"}

base64_keywords := {"base64", "encoded_secret", "token_base64"}

default_keywords := {"default", "template", "blueprint"}

api_keywords := {"api_key", "service_token", "oauth_token", "refresh_token"}

script_keywords := {"script", "user_data", "init_script", "startup_script"}

is_credential_attr(name) {
    lowercase_name := lower(name)
    keyword := hardcoded_credential_keywords[_]
    contains(lowercase_name, keyword)
}

is_config_attr(name) {
    lowercase_name := lower(name)
    keyword := config_keywords[_]
    contains(lowercase_name, keyword)
}

is_env_attr(name) {
    lowercase_name := lower(name)
    keyword := env_keywords[_]
    contains(lowercase_name, keyword)
}

is_base64_attr(name) {
    lowercase_name := lower(name)
    keyword := base64_keywords[_]
    contains(lowercase_name, keyword)
}

is_default_attr(name) {
    lowercase_name := lower(name)
    keyword := default_keywords[_]
    contains(lowercase_name, keyword)
}

is_api_attr(name) {
    lowercase_name := lower(name)
    keyword := api_keywords[_]
    contains(lowercase_name, keyword)
}

is_script_attr(name) {
    lowercase_name := lower(name)
    keyword := script_keywords[_]
    contains(lowercase_name, keyword)
}

check_static_credential(value) {
    value.ir_type == "String"
    value.value != ""
}

check_base64_static(value) {
    value.ir_type == "String"
    regex.match("^[A-Za-z0-9+/]+={0,2}$", value.value)
}

Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""
    atomic_units := glitch_lib.all_atomic_units(parent)
    node := atomic_units[_]
    attrs := glitch_lib.all_attributes(node)
    attr := attrs[_]

    is_credential_attr(attr.name)
    check_static_credential(attr.value)

    result := {
        "type": "sec_hard_secr",
        "element": attr,
        "path": parent.path,
        "description": "Use of Hard-coded Credentials - Sensitive credentials are embedded directly in the code or configuration. (CWE-798)"
    }
}

